<?php
namespace Tests\Feature;
use App\Models\{BookingServis,JenisServis,ServiceStaffProfile,TechnicianTimeOff,User};
use App\Services\{BookingServisService,ServicePersonnelAvailabilityService,ServisService};
use Carbon\Carbon;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use RuntimeException;
use Tests\TestCase;
class ServicePersonnelPhase3ATest extends TestCase { use DatabaseTransactions;
 private function staff():ServiceStaffProfile{$p=\App\Models\Petugas::where('status','aktif')->firstOrFail();$profile=ServiceStaffProfile::where('id_petugas',$p->id_petugas)->firstOrFail();$profile->update(['can_be_technician'=>true,'is_bookable'=>true]);return $profile->fresh('petugas');}
 private function date():string{return Carbon::today()->next(Carbon::TUESDAY)->toDateString();}
 private function type():JenisServis{return JenisServis::where('status','aktif')->firstOrFail();}
 private function memberVehicle(User $member):\App\Models\KendaraanPelanggan{$vehicle=$member->pelanggan->kendaraan()->where('status','aktif')->first();return $vehicle?:$member->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Personnel UI','nomor_polisi'=>'PU-'.random_int(1000,9999),'kilometer'=>10000,'status'=>'aktif']);}
 public function test_active_technician_is_listed_and_non_technician_is_not():void{$profile=$this->staff();$list=app(ServicePersonnelAvailabilityService::class)->technicians($this->date(),'10:00',$this->type()->id_jenis_servis);$this->assertContains($profile->id_petugas,collect($list)->pluck('id')->all());$profile->update(['can_be_technician'=>false]);$this->assertNotContains($profile->id_petugas,collect(app(ServicePersonnelAvailabilityService::class)->technicians($this->date(),'10:00',$this->type()->id_jenis_servis))->pluck('id')->all());}
 public function test_time_off_and_outside_hours_make_technician_unavailable():void{$profile=$this->staff();TechnicianTimeOff::create(['id_petugas'=>$profile->id_petugas,'date'=>$this->date(),'reason'=>'Cuti']);$row=collect(app(ServicePersonnelAvailabilityService::class)->technicians($this->date(),'10:00',$this->type()->id_jenis_servis))->firstWhere('id',$profile->id_petugas);$this->assertSame('time_off',$row['availability_status']);TechnicianTimeOff::where('id_petugas',$profile->id_petugas)->delete();$row=collect(app(ServicePersonnelAvailabilityService::class)->technicians($this->date(),'18:00',$this->type()->id_jenis_servis))->firstWhere('id',$profile->id_petugas);$this->assertSame('unavailable',$row['availability_status']);}
 public function test_member_safe_endpoint_exposes_no_private_staff_fields():void{$profile=$this->staff();$member=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->firstOrFail();$response=$this->actingAs($member)->getJson(route('pelanggan.booking-servis.technicians',['date'=>$this->date(),'time'=>'10:00','jenis_servis_id'=>$this->type()->id_jenis_servis]));$response->assertOk()->assertJsonStructure(['technicians'=>[['id','display_name','title','specialization','experience_years','availability_status','available']]])->assertJsonMissing(['no_hp','email','password','salary','internal_notes']);}
 public function test_optional_and_valid_preference_are_supported_but_invalid_is_rejected():void{$profile=$this->staff();$member=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->firstOrFail();$vehicle=$member->pelanggan->kendaraan()->where('status','aktif')->first();if(!$vehicle)$vehicle=$member->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Personnel','nomor_polisi'=>'PT-'.random_int(1000,9999),'kilometer'=>10000,'status'=>'aktif']);$service=app(BookingServisService::class);$date=$this->date();$plain=$service->create($member->pelanggan->id_pelanggan,$vehicle->id_kendaraan_pelanggan,$this->type()->id_jenis_servis,$date,'10:00',null,null);$this->assertNull($plain->id_preferred_petugas);$preferred=$service->create($member->pelanggan->id_pelanggan,$vehicle->id_kendaraan_pelanggan,$this->type()->id_jenis_servis,$date,'13:00',null,null,$profile->id_petugas);$this->assertSame($profile->id_petugas,$preferred->id_preferred_petugas);$profile->update(['can_be_technician'=>false]);$this->expectException(RuntimeException::class);$service->create($member->pelanggan->id_pelanggan,$vehicle->id_kendaraan_pelanggan,$this->type()->id_jenis_servis,$date,'14:00',null,null,$profile->id_petugas);}
 public function test_member_booking_page_contains_personnel_preference_integration():void{$member=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->firstOrFail();$vehicle=$this->memberVehicle($member);$response=$this->withViewErrors([])->withoutMiddleware()->actingAs($member)->get(route('pelanggan.booking-servis.create',['kendaraan'=>$vehicle->id_kendaraan_pelanggan]));$response->assertOk()->assertSee('booking-servis\\/technicians',false)->assertSee('id_preferred_petugas',false)->assertSee('display_name',false)->assertSee('Tidak Ada Preferensi',false)->assertSee('AbortController',false);}
 public function test_member_booking_detail_distinguishes_preference_from_final_assignment():void{$profile=$this->staff();$member=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->firstOrFail();$vehicle=$this->memberVehicle($member);$booking=app(BookingServisService::class)->create($member->pelanggan->id_pelanggan,$vehicle->id_kendaraan_pelanggan,$this->type()->id_jenis_servis,$this->date(),'10:00',null,null,$profile->id_petugas);$this->actingAs($member)->get(route('pelanggan.booking-servis.show',$booking))->assertOk()->assertSee('Preferensi Teknisi')->assertSee($profile->petugas->nama_lengkap)->assertSee('Penugasan teknisi final');}
 public function test_admin_can_manage_personnel_profile():void{$admin=User::whereHas('role',fn($q)=>$q->where('nama_role','admin'))->firstOrFail();$profile=ServiceStaffProfile::firstOrFail();$this->actingAs($admin)->put(route('admin.servis.personnel.profile.update',$profile),['can_be_technician'=>1,'is_bookable'=>1,'experience_years'=>5,'specializations'=>[]])->assertRedirect();$this->assertTrue((bool)$profile->fresh()->can_be_technician);}
 public function test_final_technician_and_service_advisor_assignment_persist():void{$tech=$this->staff();$advisor=ServiceStaffProfile::where('id_petugas','!=',$tech->id_petugas)->firstOrFail();$advisor->update(['can_be_service_advisor'=>true]);$member=User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->firstOrFail();$vehicle=$member->pelanggan->kendaraan()->where('status','aktif')->first()?:$member->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Assignment','nomor_polisi'=>'AS-'.random_int(1000,9999),'kilometer'=>10000,'status'=>'aktif']);$booking=app(BookingServisService::class)->create($member->pelanggan->id_pelanggan,$vehicle->id_kendaraan_pelanggan,$this->type()->id_jenis_servis,$this->date(),'14:00',null,null);$booking->forceFill(['status'=>'diterima'])->save();$wo=app(ServisService::class)->createFromBooking($booking->id_booking_servis,$tech->id_petugas,10000,null,$advisor->id_petugas,true);$this->assertSame($tech->id_petugas,$wo->id_petugas);$this->assertSame($advisor->id_petugas,$wo->id_service_advisor);}
}
